#include <stdlib.h>

#define MAXN 2005

typedef long long ll;

int n;
int pathEdges[MAXN][MAXN];
ll pathTickets[MAXN][MAXN];

int main() {
    scanf("%d", &n);

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            pathEdges[i][j] = (i == j ? 0 : 1e9);

