        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (pathEdges[i][j] > pathEdges[i][k] + pathEdges[k][j])
                    pathEdges[i][j] = pathEdges[i][k] + pathEdges[k][j];

    int m;
