    int A[100005], B[100005];
    ll C[100005];

    for (int i = 0; i < m; i++) {
        scanf("%d %d %lld", &A[i], &B[i], &C[i]);
        A[i]--; B[i]--;
    }

    for (int u = 0; u < n; u++) {
        for (int v = 0; v < n; v++) {
            ll sum = 0;
            for (int t = 0; t < m; t++) {
                int a = A[t], b = B[t];
                if (pathEdges[u][a] + pathEdges[a][v] == pathEdges[u][v] &&
